/** Public entry point — the only module consumers/docs should import from. */

export { useDataGridHistory, type UseDataGridHistoryOptions, type UseDataGridHistoryResult } from "./use-data-grid-history";
export { useDataGridState, type UseDataGridStateOptions, type UseDataGridStateResult } from "./use-data-grid-state";

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { applyChange, createHistory, isDev, type DataChange } from "@/registry/default/components/data-grid/data-grid";

/** Options for {@link useDataGridHistory}. */
export type UseDataGridHistoryOptions<TData> = {
  /** Current data array; the hook diffs/applies against this on every render (like `data` passed to `DataGrid`). */
  data: readonly TData[];
  /** Writes the next array back to the consumer's state (e.g. a `useState` setter). */
  setData: (next: readonly TData[]) => void;
  getRowId: (row: TData, index: number) => string;
  /** Maximum number of entries kept on the undo stack; oldest entries are dropped past this. */
  capacity?: number;
  /**
   * Identity of the dataset that `data` belongs to (a dataset id, a version counter). When the
   * key changes between renders, both stacks clear, so undo after a dataset swap cannot
   * reinsert rows from the old dataset. Omit it and reset with `clear()` instead.
   */
  datasetKey?: string | number;
  /**
   * Which `DataChange.source` values go on the undo stack. Defaults to every source except
   * `"stream"` — a 100-updates/s `updateCells` feed would otherwise evict the user's whole undo
   * stack within seconds. Pass a list to change the set, for example
   * `["edit", "paste", "fill", "delete", "row-op", "import", "stream"]` to record streams too.
   * `setData` still runs for every change, recorded or not.
   */
  recordSources?: readonly DataChange<TData>["source"][];
};

// Fires at most once per app, dev-only: undo ran over a sparse (lazy) data array.
let warnedSparseData = false;

// `Array.prototype.some` skips holes (the callback never runs for missing indices), so hole
// detection must test indices, not values.
function hasSparseHoles(data: readonly unknown[]): boolean {
  for (let i = 0; i < data.length; i++) if (!(i in data)) return true;
  return false;
}

/** Sources `useDataGridHistory` records when `recordSources` is omitted — everything a user did on purpose. */
const DEFAULT_RECORD_SOURCES: readonly DataChange<unknown>["source"][] = [
  "edit",
  "paste",
  "fill",
  "delete",
  "row-op",
  "import",
  "history",
  "app",
];

/** Return value of {@link useDataGridHistory}. */
export type UseDataGridHistoryResult<TData> = {
  /** Pass straight through as `DataGrid`'s `onDataChange`: records the change, then writes `next` via `setData`. */
  onDataChange: (next: readonly TData[], change: DataChange<TData>) => void;
  /** Pass as `DataGrid`'s `onUndo`. No-op when nothing to undo. */
  undo: () => void;
  /** Pass as `DataGrid`'s `onRedo`. No-op when nothing to redo. */
  redo: () => void;
  canUndo: boolean;
  canRedo: boolean;
  /** Number of entries on the undo stack; 0 when there is nothing to undo. */
  historySize: number;
  /** Clears both stacks. A dataset change clears them itself when `datasetKey` changes; use `clear` for an imperative reset. */
  clear: () => void;
  /**
   * Imperatively registers a programmatic change the consumer has ALREADY applied to `data`
   * (e.g. a set-row-count batch, a batch-save rollback) as one undo entry on the same stack -
   * this hook does not write data here, the consumer owns the array. Deliberately recorded
   * regardless of `recordSources`: an explicit call is intent, not a gesture stream. `label`
   * is an optional human-readable entry label (it also works as a field on `change` itself).
   */
  record: (change: DataChange<TData>, label?: string) => void;
};

/**
 * Op-based undo/redo wired to a consumer-owned data array. Plugs into core's
 * `onDataChange`/`onUndo`/`onRedo` extension points with no core edits.
 *
 * Design: takes `data` + `setData` (mirroring `useState`'s tuple) rather than owning
 * the array itself, so it composes with any state source (useState, a store, a server
 * mutation) — the consumer wires one setter, not a whole controlled-component contract.
 */
export function useDataGridHistory<TData>(opts: UseDataGridHistoryOptions<TData>): UseDataGridHistoryResult<TData> {
  const { data, setData, getRowId, capacity, recordSources, datasetKey } = opts;
  const history = useMemo(() => createHistory<TData>({ capacity }), [capacity]);
  // history's canUndo/canRedo are getters on a mutable object; this forces a re-render
  // after every mutating call so callers see them update even when `setData` alone wouldn't
  // re-render this hook (e.g. `clear()`, or a consumer setter that dedupes identical arrays).
  const [, forceUpdate] = useState(0);

  // stale entries reference the old dataset: undo after a swap would resurrect dead rows
  const prevDatasetKey = useRef(datasetKey);
  useEffect(() => {
    if (prevDatasetKey.current === datasetKey) return;
    prevDatasetKey.current = datasetKey;
    history.clear();
    forceUpdate((n) => n + 1);
  }, [datasetKey, history]);

  // mirrors the latest data/getRowId for undo/redo, which run outside the triggering render.
  const dataRef = useRef(data);
  dataRef.current = data;
  const getRowIdRef = useRef(getRowId);
  getRowIdRef.current = getRowId;

  const recorded = useMemo(
    () => new Set<DataChange<TData>["source"]>(recordSources ?? DEFAULT_RECORD_SOURCES),
    [recordSources],
  );

  const onDataChange = useCallback(
    (next: readonly TData[], change: DataChange<TData>) => {
      if (recorded.has(change.source)) history.push(change);
      setData(next);
      forceUpdate((n) => n + 1);
    },
    [history, setData, recorded],
  );

  const undo = useCallback(() => {
    const change = history.undo();
    if (!change) return;
    // Sparse (lazy) data needs a hole-tolerant getRowId and skips evicted rows silently — flag once, not per undo.
    if (!warnedSparseData && isDev() && hasSparseHoles(dataRef.current)) {
      warnedSparseData = true;
      console.warn(
        "[data-grid-history] undo ran over a sparse (lazy) data array: unloaded rows are holes and their ops are skipped. Use a hole-tolerant getRowId and pass a datasetKey (or call clear()) on lazy.reset() or a dataset swap.",
      );
    }
    setData(applyChange(dataRef.current, change, getRowIdRef.current));
    forceUpdate((n) => n + 1);
  }, [history, setData]);

  const redo = useCallback(() => {
    const change = history.redo();
    if (!change) return;
    setData(applyChange(dataRef.current, change, getRowIdRef.current));
    forceUpdate((n) => n + 1);
  }, [history, setData]);

  const clear = useCallback(() => {
    history.clear();
    forceUpdate((n) => n + 1);
  }, [history]);

  const record = useCallback(
    (change: DataChange<TData>, label?: string) => {
      history.push(label ? { ...change, label } : change);
      forceUpdate((n) => n + 1);
    },
    [history],
  );

  return {
    onDataChange,
    undo,
    redo,
    canUndo: history.canUndo,
    canRedo: history.canRedo,
    historySize: history.size,
    clear,
    record,
  };
}

"use client";

import { useCallback, useState } from "react";
import { applyChange, type DataChange } from "@/registry/default/components/data-grid/data-grid";
import { useDataGridHistory } from "./use-data-grid-history";

/** Options for {@link useDataGridState}. */
export type UseDataGridStateOptions<TData> = {
  getRowId: (row: TData, index: number) => string;
  /** Maximum number of entries kept on the undo stack; oldest entries are dropped past this. */
  capacity?: number;
  /**
   * Identity of the dataset; a change between renders clears both history stacks.
   * See `useDataGridHistory`'s `datasetKey`.
   */
  datasetKey?: string | number;
};

/** Return value of {@link useDataGridState}, spreadable straight onto `<DataGrid {...grid} />`. */
export type UseDataGridStateResult<TData> = {
  data: readonly TData[];
  getRowId: (row: TData, index: number) => string;
  onDataChange: (next: readonly TData[], change: DataChange<TData>) => void;
  onUndo: () => void;
  onRedo: () => void;
  /**
   * For a toolbar's undo/redo buttons, outside the spreadable `DataGrid` props. `clear` empties
   * both stacks for an imperative reset — it lives on this sub-object, not the
   * spreadable top level, to avoid a future prop-name collision on the `<DataGrid {...grid} />`
   * spread.
   */
  history: {
    canUndo: boolean;
    canRedo: boolean;
    /** Number of entries on the undo stack; 0 when there is nothing to undo. */
    historySize: number;
    undo: () => void;
    redo: () => void;
    clear: () => void;
    /**
     * Applies a programmatic change (the consumer-built op batch) to the hook-owned data AND
     * registers it as one undo entry - unlike the bare `useDataGridHistory` `record`, which only
     * registers, because here the hook owns the array and the consumer has no other write path.
     */
    record: (change: DataChange<TData>, label?: string) => void;
  };
};

/**
 * Quick-start grid state with undo/redo: wires `useState` + {@link useDataGridHistory}
 * into one spreadable object.
 *
 * "Uncontrolled" here means the consumer does not own the array between renders — the hook does —
 * NOT the core's `defaultData` semantics. It spreads a CONTROLLED `data` prop into the grid and
 * re-feeds it every render; undo/redo work precisely because of that echo. Never treat it like
 * `defaultData` (set once, grid-owned afterwards) and pass it alongside your own data.
 *
 * ```tsx
 * const grid = useDataGridState(rows, { getRowId: (r) => r.id });
 * <DataGrid {...grid} columns={columns} />
 * ```
 */
export function useDataGridState<TData>(
  defaultRows: readonly TData[],
  opts: UseDataGridStateOptions<TData>,
): UseDataGridStateResult<TData> {
  const { getRowId, capacity, datasetKey } = opts;
  const [data, setData] = useState<readonly TData[]>(defaultRows);
  const { onDataChange, undo, redo, canUndo, canRedo, clear, historySize, record: historyRecord } = useDataGridHistory({
    data,
    setData,
    getRowId,
    capacity,
    datasetKey,
  });
  // stable identity: useDataGridRowIdToViewRow keys its O(n) Map build on getRowId identity.
  const gridGetRowId = useCallback((row: TData, index: number) => getRowId(row, index), [getRowId]);

  const record = useCallback(
    (change: DataChange<TData>, label?: string) => {
      const tagged = label ? { ...change, label } : change;
      setData((current) => applyChange(current, tagged, gridGetRowId));
      historyRecord(tagged);
    },
    [historyRecord, gridGetRowId],
  );

  return {
    data,
    getRowId: gridGetRowId,
    onDataChange,
    onUndo: undo,
    onRedo: redo,
    history: { canUndo, canRedo, historySize, undo, redo, clear, record },
  };
}
